(* [comment removed for export] *)
Definition g_hang (x : Z) : Z := if x mod 32 =? 0 then 0 else 32 - x mod 32.
(* [comment removed for export] *)
Definition g_sls (DX SX : Z) : Z := g_hang DX - g_hang SX + (if g_hang SX <? g_hang DX then 0 else 32).
(* [comment removed for export] *)
Definition g_fw (DX : Z) : bool := negb (DX mod 32 =? 0).
(* [comment removed for export] *)
Definition g_dp (DX DW : Z) : bool := negb (DX mod 32 =? 0) && (DW <? 32 - DX mod 32).
(* [comment removed for export] *)
Definition g_nfw (DX DW : Z) : Z := if g_dp DX DW then 0 else (DW - g_hang DX) / 32.
Definition g_lwb (DX DW : Z) : Z := (DW + DX) mod 32.
(* [comment removed for export] *)
Definition g_nolast (DX DW : Z) : bool := g_dp DX DW || (g_lwb DX DW =? 0).
(* [comment removed for export] *)
Definition g_f6 (DX SX : Z) : bool := DX mod 32 <? SX mod 32.
Definition g_f7 (SX DW : Z) : bool := negb (32 - SX mod 32 <? DW).
(* [comment removed for export] *)
Definition g_f3 (DX SX DW : Z) : bool := negb (32 - g_sls DX SX <? g_lwb DX DW).
(* [comment removed for export] *)
Definition g_smax (DX SX DW : Z) : Z :=
  Z.max (if g_fw DX then SX / 32 + (if g_f6 DX SX && negb (g_f7 SX DW) then 1 else 0) else 0)
        (Z.max (if g_nfw DX DW =? 0 then 0 else (SX + g_hang DX) / 32 + g_nfw DX DW)
               (if g_nolast DX DW then 0 else (SX + g_hang DX) / 32 + g_nfw DX DW + (if g_f3 DX SX DW then 0 else 1))).

